<template><div class="adapter-market"><section class="market-hero"><div><span>平台连接目录</span><h2>Adapter 市场</h2><p>浏览平台 Adapter，并由宿主从 GitHub 下载、预览和确认安装。</p></div><el-button round :loading="loading" @click="load">刷新目录</el-button></section><section class="filters"><el-input v-model="keyword" placeholder="搜索 Adapter、平台、作者或仓库" clearable /><div><el-button v-for="item in platforms" :key="item" round size="small" :type="platform === item ? 'primary' : 'default'" @click="platform = item">{{ item }}</el-button></div></section><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon /><el-alert v-if="message" :title="message" :type="messageType" closable show-icon @close="message = ''" /><section class="market-grid"><el-skeleton v-if="loading" :rows="6" animated /><article v-for="entry in filtered" :key="entry.id" class="market-card"><div class="card-heading"><span class="platform-mark">{{ entry.platform.slice(0, 1).toUpperCase() }}</span><div><h3>{{ entry.name }}</h3><small>{{ entry.id }} · v{{ entry.version }}</small></div><el-tag size="small">{{ entry.platform }}</el-tag></div><p>{{ entry.description || '暂无描述。' }}</p><dl><div><dt>作者</dt><dd>{{ entry.authors.join('、') || 'Unknown' }}</dd></div><div><dt>仓库</dt><dd>{{ entry.repository || '—' }}</dd></div><div><dt>下载</dt><dd>{{ entry.downloadCount?.toLocaleString() ?? '—' }}</dd></div></dl><el-alert v-if="entry.installedVersion" :title="`已安装 v${entry.installedVersion}`" type="success" :closable="false" /><el-alert v-if="entry.health !== 'available' && entry.health !== 'healthy'" :title="`目录状态：${entry.health}`" type="warning" :closable="false" /><el-button type="primary" :loading="busyId === entry.id" :disabled="!entry.repository || Boolean(busyId)" @click="prepare(entry)">{{ entry.installedVersion ? '更新 / 重装' : '从 GitHub 安装' }}</el-button></article><el-empty v-if="!loading && !filtered.length" description="没有匹配的 Adapter。" /></section><AdapterInstallDialog :visible="installVisible" title="确认从 GitHub 安装 Adapter" :file="null" :preview="preview" :replace="replace" :busy="installBusy" :error="installError" @update:visible="close" @update:file="() => undefined" @update:replace="replace = $event" @confirm="confirm" /></div></template>
<script setup lang="ts">import AdapterInstallDialog from '../adapters/components/AdapterInstallDialog.vue'; import { useAdapterMarketPage } from './AdapterMarket'; const { keyword, platform, platforms, filtered, loading, error, message, messageType, busyId, preview, replace, installVisible, installBusy, installError, load, prepare, confirm, close } = useAdapterMarketPage()</script>
<style scoped src="./AdapterMarket.css"></style>
